-- Existing fictional patient is connected only in the isolated test database.
insert into auth.users(id)values(tests.id(9));insert into auth.sessions values(tests.id(109),tests.id(9));
insert into reda_profiles(user_id,role)values(tests.id(9),'patient');
update reda_patients set auth_user_id=tests.id(9)where id=tests.id(700003);
set role authenticated;select tests.login(1,'aal2',103);select tests.workspace('dashboard-test');
select set_config('tests.msg_token',reda_dashboard_patient(tests.id(700003))->>'token',false);
select set_config('tests.msg_receipt',reda_dashboard_act(tests.id(700003),current_setting('tests.msg_token'),tests.id(760001),'send_message','Fiktiv fråga: vilken övning behöver du hjälp med?',current_date+1)::text,false);
select tests.ok(current_setting('tests.msg_receipt')::jsonb->>'message_sent'='true','message is actually delivered in Reda after approval');
select tests.ok(reda_dashboard_act(tests.id(700003),current_setting('tests.msg_token'),tests.id(760001),'send_message','Fiktiv fråga: vilken övning behöver du hjälp med?',current_date+1)=current_setting('tests.msg_receipt')::jsonb,'lost send response cannot duplicate the message');
select tests.ok(reda_evaluate_progression(tests.id(700003),tests.id(760101))->>'code'='pending_review','open conversation blocks progression');
select tests.denied('select reda_dashboard_act(tests.id(700004),reda_dashboard_patient(tests.id(700004))->>''token'',tests.id(760002),''send_message'',''Unconnected patient cannot receive'',current_date+1)','42501','messaging cannot onboard an unconnected patient');
select set_config('tests.before_reply',reda_dashboard_patient(tests.id(700003))->>'token',false);
select tests.login(9,'aal1',109);
select tests.ok(jsonb_array_length(reda_patient_messages()->'messages')=1,'patient reads only their delivered conversation');
select tests.ok(reda_patient_messages()->>'reply_to'=tests.id(760001)::text,'patient can answer latest clinician message');
select reda_patient_reply(tests.id(760001),tests.id(760003),'Det gäller bensparken. Jag fastnar i slutet.');
select tests.ok(reda_patient_reply(tests.id(760001),tests.id(760003),'Det gäller bensparken. Jag fastnar i slutet.')->>'sent'='true','patient reply retry is idempotent');
select tests.denied('select reda_patient_reply(tests.id(760001),tests.id(760003),''Different response cannot replace history.'')','23505','changed retry cannot rewrite the patient reply');
select tests.denied('select reda_patient_reply(tests.id(760001),tests.id(760004),''Another response to the same message.'')','40001','one response per prompt prevents duplicate replies');
select tests.ok(reda_patient_messages()->'reply_to'='null'::jsonb,'answered prompt no longer offers another reply');
select tests.login(2,'aal1',101);
select tests.ok(jsonb_array_length(reda_patient_messages()->'messages')=0,'another patient cannot read conversation');
select tests.denied('select reda_patient_reply(tests.id(760001),tests.id(760004),''Forged patient response.'')','42501','another patient cannot reply');
select tests.login(9,'aal1',999);
select tests.denied('select reda_patient_messages()','42501','revoked patient session cannot read messages');
select tests.login(1,'aal2',103);select tests.workspace('dashboard-test');
select tests.ok((reda_dashboard_patient(tests.id(700003))->'patient'->>'new_reply')::boolean,'patient reply reopens the work queue despite future follow-up');
select tests.denied('select reda_dashboard_act(tests.id(700003),current_setting(''tests.before_reply''),tests.id(760005),''resolve_cases'',''Old proposal cannot resolve a new reply.'')','40001','new reply invalidates pending clinician approval');
select tests.ok(jsonb_array_length(reda_dashboard_patient(tests.id(700003))->'messages')=2,'clinician sees exact reply and original question');
select reda_dashboard_act(tests.id(700003),reda_dashboard_patient(tests.id(700003))->>'token',tests.id(760006),'follow_up','Bedöm patientens svar vid uppföljningen.',current_date+1);
select tests.ok(not(reda_dashboard_patient(tests.id(700003))->'patient'->>'new_reply')::boolean,'scheduled handling moves reviewed reply to waiting list');
select tests.ok(reda_evaluate_progression(tests.id(700003),tests.id(760102))->>'code'='pending_review','scheduling or replying does not clear clinical conversation gate');
select tests.ok(reda_dashboard_act(tests.id(700003),reda_dashboard_patient(tests.id(700003))->>'token',tests.id(760007),'resolve_cases','Patientens svar är bedömt och hanterat i detta fiktiva fall.')->>'message_count'='2','explicit assessment resolves the whole visible conversation');
select tests.ok(reda_evaluate_progression(tests.id(700003),tests.id(760103))->>'code'<>'pending_review','explicit conversation assessment releases only the conversation gate');
select tests.workspace('clinic-b');
select tests.denied('select reda_dashboard_patient(tests.id(700003))','42501','conversation cannot cross workspace');
reset role;
select tests.ok((select count(*)=1 from private.reda_clinic_messages where id=tests.id(760001)),'exactly one clinician message after retry');
select tests.ok((select count(*)=1 from reda_audit_events where action='patient_message_replied' and metadata->>'message_id'=tests.id(760003)::text),'patient reply audit is idempotent');
